            <div class="db-mixl">${AREAS.map(a => `<a class="db-mr" href="#${a.go}"><i class="h-${a.k}"></i><span>${ovShort[a.k]}</span><b>${eur0(V[a.k])}</b><em>${T ? fmtNum(pct(V[a.k], T), 0) : 0}%</em></a>`).join('')}</div>
