  // legge il preventivo dai campi della pagina (senza salvare)
  function pvFromForm() {
    const ed = $('#pv-ed'); if (!ed) return null;
    const p = pvGet(ed.dataset.id); if (!p) return null;
    pvRefresh(p);
    $$('[data-pvf]', ed).forEach(el => { const k = el.dataset.pvf, v = el.value; if (k.startsWith('cliente.')) { p.cliente = p.cliente || {}; p.cliente[k.slice(8)] = v.trim(); } else if (k === 'valid' || k === 'sconto' || k === 'iva' || k === 'spz') p[k] = num(v); else p[k] = v; });
    $$('[data-pvlp]', ed).forEach(el => { const l = p.righe[+el.dataset.pvlp]; if (!l) return; const v = String(el.value).trim(), auto = pvPubFor(p, l.it, l.c); if (v === '') { l.p = auto; l.man = false; } else { const n = num(v); l.man = auto == null || Math.abs(n - auto) > .004; l.p = n; } });
    $$('[data-pvls]', ed).forEach(el => { const l = p.righe[+el.dataset.pvls]; if (l) l.sc = Math.min(100, Math.max(0, num(el.value))); });
    $$('[data-pvpr]', ed).forEach(el => { const [i0, k] = el.dataset.pvpr.split(':'), r = (p.pers || [])[+i0]; if (!r) return; const v = String(el.value).trim(); if (k === 'd') { if (v !== r.d) { r.d = v; } } else if (k === 'q') { const nq = v === '' ? null : num(v); if (nq !== r.q) r.q = nq; } else if (k === 'p') r.p = num(v); else if (k === 'slot') r.slot = v; });
    return p;
  }
  function pvTotUpd(p) {
    p = p || pvFromForm(); if (!p) return;
    const t = pvTotals(p);
    p.righe.forEach((l, i) => { const td = $(`[data-pvlt="${i}"]`); if (td) td.textContent = l.p != null ? eur(pvLineTot(l)) : '—';
      const la = $(`[data-pvla="${i}"]`); if (la) { const a = pvAcq(l.it, l.c), u = pvLineUnit(l), net = u != null ? u * (1 - num(l.sc) / 100) : null; la.className = 'pv-lacq' + (a != null && net != null && net < a ? ' neg' : ''); la.textContent = a == null ? 'acquisto: —' : `acq. ${eur(a)}${net ? ` · margine ${fmtNum((net - a) / net * 100, 0)}%` : ''}`; } });
    const el = $('#pv-tots'); if (!el) return;
    const keepFocus = document.activeElement && document.activeElement.id === 'pv-gsc';
    if (keepFocus) { const set = (id, v) => { const x = $('#' + id); if (x) x.textContent = v; }; set('pv-t-sc', '− ' + eur(t.sc)); set('pv-t-imp', eur(t.imp)); set('pv-t-iva', eur(t.iva)); set('pv-t-tot', eur(t.tot)); return; }
    el.innerHTML = `<div class="pv-tr"><span>${p.solo && !p.righe.length ? 'Totale lavorazioni' : 'Totale prodotti'}</span><b>${eur(t.sub)}</b></div>
      <div class="pv-tr"><span>Sconto sul totale</span><span class="pv-gs"><input id="pv-gsc" data-pvf="sconto" inputmode="decimal" value="${num(p.sconto) ? esc(fmtIn(p.sconto)) : ''}" placeholder="0"> %</span><b id="pv-t-sc">− ${eur(t.sc)}</b></div>
      <div class="pv-tr"><span>Imponibile</span><b id="pv-t-imp">${eur(t.imp)}</b></div>
      <div class="pv-tr"><span>IVA ${fmtNum(num(p.iva), 0)}%</span><b id="pv-t-iva">${eur(t.iva)}</b></div>
      <div class="pv-tr t"><span>Totale</span><b id="pv-t-tot">${eur(t.tot)}</b></div>
      <div class="pv-int"${pvCli ? ' hidden' : ''}><span>Solo per te · non va nel PDF</span>${t.noCost ? `<small>${t.noCost} righe senza prezzo d'acquisto: margine incompleto</small>` : ''}<div class="pv-tr"><span>Costo d'acquisto</span><b>${eur(t.costo)}</b></div><div class="pv-tr"><span>Margine</span><b class="${t.marg >= 0 ? 'pos' : 'neg'}">${eur(t.marg)}${t.imp ? ` · ${fmtNum(t.marg / t.imp * 100, 0)}%` : ''}</b></div></div>`;
  }
  function pvLineEdit(i) {
    const p = pvFromForm(); if (!p) return; const l = p.righe[i]; if (!l) return;
    const sz = l.sz || Object.keys(l.q);
    openSheet(`${l.n} · ${l.cn}`, `<p class="muted small" style="margin:0 0 10px">Quantità per taglia. Lascia vuoto per togliere una taglia.</p><div class="pv-lq">${sz.map(s => `<label class="f"><span>${esc(s)}</span><input data-lq="${esc(s)}" inputmode="numeric" value="${num(l.q[s]) ? esc(String(l.q[s])) : ''}"></label>`).join('')}</div>`, () => {
      const q = {}; $$('#sheet-body [data-lq]').forEach(x => { const v = num(x.value); if (v > 0) q[x.dataset.lq] = v; });
      if (!Object.keys(q).length) p.righe.splice(i, 1); else l.q = q;
      pvSave(p); return true;
    }, null, 'Salva');
  }

  /* ---------- v89: modifica prodotti, ordine e sostituzione righe, scheda tecnica PDF ---------- */
  // --- spostare le righe trascinando la maniglia (mouse e dito) ---
  function dragRows(tbody, onMove) {
    if (!tbody || tbody._drag) return; tbody._drag = 1;
    tbody.addEventListener('pointerdown', e => {
      const h = e.target.closest('[data-dragh]'); if (!h || e.button > 0) return;
      const row = h.closest('tr'), rows = [...tbody.children], from = rows.indexOf(row); if (from < 0 || rows.length < 2) return;
      e.preventDefault(); h.setPointerCapture(e.pointerId);
      const y0 = e.clientY, rect = rows.map(r => r.getBoundingClientRect()); let to = from, scr = 0, lastY = e.clientY;
      row.classList.add('dr-on'); document.body.classList.add('dr-busy');
      const mark = () => rows.forEach((r, i) => { if (r === row) return; const sh = from < to && i > from && i <= to ? -rect[from].height : from > to && i >= to && i < from ? rect[from].height : 0; r.style.transform = sh ? `translateY(${sh}px)` : ''; });
      const move = ev => { lastY = ev.clientY; const dy = ev.clientY - y0 + (window.scrollY - scr0); row.style.transform = `translateY(${dy}px)`; const c = rect[from].top + rect[from].height / 2 + dy; let k = from; rect.forEach((r, i) => { const mid = r.top + r.height / 2; if (i < from && c < mid) k = Math.min(k, i); if (i > from && c > mid) k = Math.max(k, i); }); if (k !== to) { to = k; mark(); } };
      const scr0 = window.scrollY;
      const tick = () => { if (!row.classList.contains('dr-on')) return; const vh = innerHeight, mv = lastY - y0; if (mv < -6 && lastY < 70) window.scrollBy(0, -10); else if (mv > 6 && lastY > vh - 110) window.scrollBy(0, 10); scr = requestAnimationFrame(tick); };
      scr = requestAnimationFrame(tick);
      const up = () => { h.removeEventListener('pointermove', move); h.removeEventListener('pointerup', up); h.removeEventListener('pointercancel', up); cancelAnimationFrame(scr); row.classList.remove('dr-on'); document.body.classList.remove('dr-busy'); rows.forEach(r => (r.style.transform = '')); if (to !== from) onMove(from, to); };
      h.addEventListener('pointermove', move); h.addEventListener('pointerup', up); h.addEventListener('pointercancel', up);
    });
    tbody.addEventListener('keydown', e => { const h = e.target.closest('[data-dragh]'); if (!h || (e.key !== 'ArrowUp' && e.key !== 'ArrowDown')) return; e.preventDefault(); const rows = [...tbody.children], i = rows.indexOf(h.closest('tr')), j = i + (e.key === 'ArrowUp' ? -1 : 1); if (j >= 0 && j < rows.length) onMove(i, j, true); });
  }
  const moveItem = (a, from, to) => { const [x] = a.splice(from, 1); a.splice(to, 0, x); return a; };
  const DRAG_H = '<button type="button" class="dr-h" data-dragh title="Trascina per spostare (o frecce ↑ ↓)" aria-label="Sposta riga"><svg viewBox="0 0 24 24"><circle cx="9" cy="6" r="1.4"/><circle cx="15" cy="6" r="1.4"/><circle cx="9" cy="12" r="1.4"/><circle cx="15" cy="12" r="1.4"/><circle cx="9" cy="18" r="1.4"/><circle cx="15" cy="18" r="1.4"/></svg></button>';
