    const old = p.righe[pvR.i]; if (!old) return true;
    const { sup, id, c } = pvR.pick, cat = pvCats[sup], it = cat && cat.items.find(x => x.id === id), cc = it && it.c.find(x => x[0] === c); if (!cc) return true;
