    const nl = { sup, it: it.id, n: it.n, cl: it.cl, c: cc[0], cn: cc[1], sz, q, p: null, man: false, sc: old.sc || 0, ...(cat.tool ? { tool: 1 } : {}) };
    if (!cat.tool) { if (old.lf) nl.lf = old.lf; if (old.lr) nl.lr = old.lr; }
    nl.p = pvPubFor(p, nl.it, nl.c);
