      if (m.p != null) it.c.forEach(c => { if (pvPubMod[sup + '\u0001' + it.id + '|' + c[0]] == null) pvPubMod[sup + '\u0001' + it.id + '|' + c[0]] = m.p; });
      it.mod2 = m.agg || 1;
      it.k = amNorm(`${it.n} ${it._ok || ''}`);
