      const itemOf = l => { const c = cats[l.sup || 'payper']; return c ? c.items.find(x => x.id === l.it) : null; };
      const urlOf = l => { const c = cats[l.sup || 'payper'], it = itemOf(l), cc = it && it.c.find(x => x[0] === l.c); return c && cc ? pvImg(c, cc) : ''; };
