      if (U.length) { busy('Scarico le foto dei capi…'); const R = await pvPhotos(U, 700); U.forEach((u, i) => ph.set(u, R[i])); }
      const LG = p.loghi || {}, hasLg = p.righe.some(l => (l.lf && LG.f) || (l.lr && LG.r));
      let mocks = [], LGF = null, LGR = null;
