          let cx = x; cols.forEach(h => { fill(hex2rgb(h)); stroke(C.line); doc.setLineWidth(.25); doc.roundedRect(cx, y + 20, 7, 4.2, .8, .8, 'FD'); color(C.muted); font('normal', 5.8); doc.text(h.toUpperCase(), cx + 3.5, y + 27.2, { align: 'center' }); cx += 13; });
