    const txt = ['Preventivo kit Torental', ...L.map(x => `- ${x.t}${x.q !== 1 ? ' × ' + fmtNum(x.q, 0) : ''}: ${eur(x.q * x.p)}`), `Imponibile: ${eur(imp)}`, `IVA 22%: ${eur(iva)}`, `Totale: ${eur(tot)}`, '', trData().nota || ''].join('\n').trim();
