          const was = w.src && w.src.descrizione === r.descrizione && num(w.src.quantita) === r.quantita && Math.abs(num(w.src.prezzo) - r.prezzo) < .0005 && Math.abs(num(w.src.importo) - r.importo) < .005;
          if (!w.src || !was) artCh = true;
