        color(C.blue); font('bold', 8); doc.text('SCHEDA TECNICA', M, 13); color(C.muted); font('normal', 8); doc.text(`${isD ? 'DDT' : 'Fattura'} n. ${dnum(d)}`, W - M, 13, { align: 'right' });
        const im = photoOf(l0), bw = 66, bh = 80;
